// TestArrayBounds checks that every buffer bound this package exports still
// equals the length of the array it governs, measured for x86_64-unknown-linux-gnu.
//
// The bound is what a caller sizes a buffer from and the array is what DCGM
// writes into. If a header release raised one without the other, a caller
// following the constant would hand DCGM a short buffer, and the library would
// write past it -- a corruption with no error return. That has to fail here.
func TestArrayBounds(t *testing.T) {
	if got := len(GroupInfo{}.EntityList); got != GroupMaxEntitiesV2 {
		t.Errorf("len(GroupInfo{}.EntityList) = %d, but GroupMaxEntitiesV2 = %d", got, GroupMaxEntitiesV2)
	}
	if got := len(FieldGroupInfo{}.FieldIds); got != MaxFieldIDsPerFieldGroup {
		t.Errorf("len(FieldGroupInfo{}.FieldIds) = %d, but MaxFieldIDsPerFieldGroup = %d", got, MaxFieldIDsPerFieldGroup)
	}
	if got := len(GroupInfo{}.GroupName); got != MaxStrLength {
		t.Errorf("len(GroupInfo{}.GroupName) = %d, but MaxStrLength = %d", got, MaxStrLength)
	}
	if got := len(FieldGroupInfo{}.FieldGroupName); got != MaxStrLength {
		t.Errorf("len(FieldGroupInfo{}.FieldGroupName) = %d, but MaxStrLength = %d", got, MaxStrLength)
	}
	if got := len(AllFieldGroup{}.FieldGroups); got != MaxNumFieldGroups {
		t.Errorf("len(AllFieldGroup{}.FieldGroups) = %d, but MaxNumFieldGroups = %d", got, MaxNumFieldGroups)
	}
	if got := int(unsafe.Sizeof(FieldValueV1{}.Value)); got != MaxBlobLength {
		t.Errorf("int(unsafe.Sizeof(FieldValueV1{}.Value)) = %d, but MaxBlobLength = %d", got, MaxBlobLength)
	}
	if got := int(unsafe.Sizeof(FieldValueV2{}.Value)); got != MaxBlobLength {
		t.Errorf("int(unsafe.Sizeof(FieldValueV2{}.Value)) = %d, but MaxBlobLength = %d", got, MaxBlobLength)
	}
}

// TestBlankOrdering checks the relationship the blank test depends on: each
// specific reason is above the blank value for its type, so the "at or above
// blank" inequality catches all of them.
func TestBlankOrdering(t *testing.T) {
	for _, c := range []struct {
		name  string
		blank int64
		cases map[string]int64
	}{
		{"int32", Int32Blank, map[string]int64{"NotFound": Int32NotFound, "NotSupported": Int32NotSupported, "NotPermissioned": Int32NotPermissioned}},
		{"int64", Int64Blank, map[string]int64{"NotFound": Int64NotFound, "NotSupported": Int64NotSupported, "NotPermissioned": Int64NotPermissioned}},
	} {
		for name, v := range c.cases {
			if v <= c.blank {
				t.Errorf("%s %s = %d, not above the blank value %d", c.name, name, v, c.blank)
			}
		}
	}
	for name, v := range map[string]float64{"NotFound": Fp64NotFound, "NotSupported": Fp64NotSupported, "NotPermissioned": Fp64NotPermissioned} {
		if v <= Fp64Blank {
			t.Errorf("fp64 %s = %v, not above the blank value %v", name, v, Fp64Blank)
		}
	}
}

// TestLimitReferences names every constant this file generates.
//
// Most of its value is at compile time: a bound that stops being generated --
// because the macro was renamed or the allowlist lost an entry -- makes this
// file fail to build, so the loss is reported by "go build" rather than
// discovered by a caller who sized a buffer from a constant that is no longer
// there.
//
// At run time it checks the values that must be distinct still are. Two
// entity-group ids collapsing onto one value would silently redirect a query
// to the wrong kind of entity, two sentinels colliding would make one reason
// unreportable, and two field types colliding would select the wrong arm of
// the value union. The buffer bounds are deliberately not compared: several of
// them are legitimately equal.
func TestLimitReferences(t *testing.T) {
	_ = []uint64{
		uint64(MaxNumDevices),
		uint64(MaxNumGroups),
		uint64(MaxNumFieldGroups),
		uint64(MaxFieldIDsPerFieldGroup),
		uint64(GroupMaxEntitiesV1),
		uint64(GroupMaxEntitiesV2),
		uint64(MaxStrLength),
		uint64(MaxBlobLength),
		uint64(GroupAllGPUs),
		uint64(GroupAllNvSwitches),
		uint64(GroupAllInstances),
		uint64(GroupAllComputeInstances),
		uint64(GroupAllEntities),
		uint64(Int8Blank),
		uint64(Int32Blank),
		uint64(Int32NotFound),
		uint64(Int32NotSupported),
		uint64(Int32NotPermissioned),
		uint64(Int64Blank),
		uint64(Int64NotFound),
		uint64(Int64NotSupported),
		uint64(Int64NotPermissioned),
		uint64(FieldTypeBinary),
		uint64(FieldTypeDouble),
		uint64(FieldTypeInt64),
		uint64(FieldTypeString),
		uint64(FieldTypeTimestamp),
	}

	seenGroupIDs := map[uint64]string{}
	for _, c := range []struct {
		name  string
		value uint64
	}{
		{"GroupAllGPUs", uint64(GroupAllGPUs)},
		{"GroupAllNvSwitches", uint64(GroupAllNvSwitches)},
		{"GroupAllInstances", uint64(GroupAllInstances)},
		{"GroupAllComputeInstances", uint64(GroupAllComputeInstances)},
		{"GroupAllEntities", uint64(GroupAllEntities)},
	} {
		if prev, dup := seenGroupIDs[c.value]; dup {
			t.Errorf("entity-group id %s and %s are both %#x", prev, c.name, c.value)
		}
		seenGroupIDs[c.value] = c.name
	}

	seenSentinels := map[uint64]string{}
	for _, c := range []struct {
		name  string
		value uint64
	}{
		{"Int8Blank", uint64(Int8Blank)},
		{"Int32Blank", uint64(Int32Blank)},
		{"Int32NotFound", uint64(Int32NotFound)},
		{"Int32NotSupported", uint64(Int32NotSupported)},
		{"Int32NotPermissioned", uint64(Int32NotPermissioned)},
		{"Int64Blank", uint64(Int64Blank)},
		{"Int64NotFound", uint64(Int64NotFound)},
		{"Int64NotSupported", uint64(Int64NotSupported)},
		{"Int64NotPermissioned", uint64(Int64NotPermissioned)},
	} {
		if prev, dup := seenSentinels[c.value]; dup {
			t.Errorf("sentinel %s and %s are both %#x", prev, c.name, c.value)
		}
		seenSentinels[c.value] = c.name
	}

	seenFieldTypes := map[uint64]string{}
	for _, c := range []struct {
		name  string
		value uint64
	}{
		{"FieldTypeBinary", uint64(FieldTypeBinary)},
		{"FieldTypeDouble", uint64(FieldTypeDouble)},
		{"FieldTypeInt64", uint64(FieldTypeInt64)},
		{"FieldTypeString", uint64(FieldTypeString)},
		{"FieldTypeTimestamp", uint64(FieldTypeTimestamp)},
	} {
		if prev, dup := seenFieldTypes[c.value]; dup {
			t.Errorf("field type %s and %s are both %#x", prev, c.name, c.value)
		}
		seenFieldTypes[c.value] = c.name
	}
}
